@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="mb-3">
    <label for="statusFilter" class="form-label">Filter by Status:</label>
    <select id="statusFilter" class="form-select w-auto" @bind="selectedFilter">
        <option value="">All</option>
        @foreach (var status in Enum.GetValues<ShipmentStatus>())
        {
            <option value="@status">@status</option>
        }
    </select>
</div>

@if (shipments is null)
{
    <p>Loading...</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking Number</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Estimated Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Destination</td>
                    <td>@shipment.Status</td>
                    <td>@shipment.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select class="form-select form-select-sm w-auto d-inline-block"
                                value="@shipment.Status"
                                @onchange="(e) => UpdateStatus(shipment.Id, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status" selected="@(status == shipment.Status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private string selectedFilter = "";

    private IEnumerable<Shipment> FilteredShipments =>
        string.IsNullOrEmpty(selectedFilter)
            ? shipments!
            : shipments!.Where(s => s.Status.ToString() == selectedFilter);

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
    }
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track a Shipment</h1>

<div class="mb-3">
    <label for="trackingInput" class="form-label">Tracking Number:</label>
    <div class="input-group w-auto">
        <input id="trackingInput" type="text" class="form-control" style="max-width: 300px;"
               @bind="trackingNumber" @bind:event="oninput" />
        <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
    </div>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">Shipment not found.</div>
}
else if (shipment is not null)
{
    <div class="card mt-3" style="max-width: 500px;">
        <div class="card-body">
            <h5 class="card-title">@shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> @shipment.Status</p>
            <p><strong>Origin:</strong> @shipment.Origin</p>
            <p><strong>Destination:</strong> @shipment.Destination</p>
            <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("yyyy-MM-dd")</p>
            <p><strong>Description:</strong> @shipment.Description</p>
            <p class="text-muted"><small>Last Updated: @shipment.LastUpdated.ToString("g")</small></p>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private Shipment? shipment;
    private bool searched;

    private async Task TrackShipment()
    {
        searched = true;
        shipment = null;
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        }
    }
}

